 total=mean_anchor+med(c['candidate'],c['batch_size'],'steady_full_predict');L.append(f"| {c['candidate']} | {c['batch_size']} | {c.get('provider_saving_percent','N/A')} | {c['full_predict_saving_percent']:.6f} | {c['full_system_saving_percent']:.9f} | {total:.9f} |")
